PARAMS = {
    "Wn":   (0.6, 0.42, 3.0),    # input nfet stack width (M4,M5) [um]
    "Ln":   (1.0, 0.5, 3.0),     # nfet length
    "rn":   (1.5, 0.5, 5.0),     # W6/W4 feedback ratio (raises vth_hi)
    "Wp":   (1.5, 0.42, 6.0),    # input pfet stack width (M1,M2)
    "Lp":   (1.0, 0.5, 3.0),     # pfet length
    "rp":   (1.0, 0.3, 4.0),     # W3/W1 feedback ratio (lowers vth_lo)
    "Linv": (0.5, 0.15, 2.0),    # output inverter length
}

def _id(lut, dev, W, L, vgs, vds, vsb):
    try:
        if vgs <= 0 or vds <= 0:
            return 0.0
        return abs(lut.op(dev, W, L, vgs, vds, vsb)["Id"])
    except Exception:
        return 0.0

def _vth(lut, dev, W, L, vgs, vds, vsb, dflt):
    try:
        return abs(lut.op(dev, W, L, max(vgs, 0.3), max(vds, 0.05), vsb)["vth"])
    except Exception:
        return dflt

def _bisect(f, lo, hi, it=40):
    flo = f(lo)
    for _ in range(it):
        mid = 0.5 * (lo + hi)
        fm = f(mid)
        if (fm > 0) == (flo > 0):
            lo, flo = mid, fm
        else:
            hi = mid
    return 0.5 * (lo + hi)

def _thresholds(lut, VDD, Wn, Ln, W6, Wp, Lp, W3):
    vgrid = np.linspace(0.05, VDD - 0.02, 120)
    # rising input: x high, M6 (vdd->n1, gate x) fights M4 (n1->vss, gate vin)
    vhi = VDD
    for vin in vgrid:
        f = lambda n1: _id(lut, "n", W6, Ln, VDD - n1, VDD - n1, n1) - _id(lut, "n", Wn, Ln, vin, n1, 0.0)
        n1 = _bisect(f, 1e-3, VDD - 1e-3)
        vt5 = _vth(lut, "n", Wn, Ln, vin - n1, VDD - n1, n1, 0.7)
        if vin - n1 > vt5:
            vhi = vin
            break
    # falling input: x low, M3 (p1->vss, gate x) fights M1 (vdd->p1, gate vin)
    vlo = 0.0
    for vin in vgrid[::-1]:
        f = lambda p1: _id(lut, "p", Wp, Lp, VDD - vin, VDD - p1, 0.0) - _id(lut, "p", W3, Lp, p1, p1, VDD - p1)
        p1 = _bisect(f, 1e-3, VDD - 1e-3)
        vt2 = _vth(lut, "p", Wp, Lp, p1 - vin, p1, VDD - p1, 1.05)
        if p1 - vin > vt2:
            vlo = vin
            break
    return vhi, vlo

def design(p, lut, spec):
    Wn, Ln, Wp, Lp = p["Wn"], p["Ln"], p["Wp"], p["Lp"]
    W6 = max(0.42, p["rn"] * Wn)
    W3 = max(0.42, p["rp"] * Wp)
    Li = p["Linv"]

    n = Netlist("vin vout vdd vss")
    # PMOS input stack + feedback
    n.M("M1", "p1", "vin", "vdd", "vdd", "pfet", Wp, Lp)
    n.M("M2", "x", "vin", "p1", "vdd", "pfet", Wp, Lp)
    n.M("M3", "vss", "x", "p1", "vdd", "pfet", W3, Lp)
    # NMOS input stack + feedback
    n.M("M5", "x", "vin", "n1", "vss", "nfet", Wn, Ln)
    n.M("M4", "n1", "vin", "vss", "vss", "nfet", Wn, Ln)
    n.M("M6", "vdd", "x", "n1", "vss", "nfet", W6, Ln)
    # output inverter -> non-inverting overall, rail-to-rail
    n.M("M7", "vout", "x", "vdd", "vdd", "pfet", 1.5, Li)
    n.M("M8", "vout", "x", "vss", "vss", "nfet", 0.6, Li)

    # predictions at nominal and worst supply
    preds = {}
    try:
        vhi, vlo = _thresholds(lut, 1.8, Wn, Ln, W6, Wp, Lp, W3)
        vhi_l, vlo_l = _thresholds(lut, 1.62, Wn, Ln, W6, Wp, Lp, W3)
        n1 = vhi - 0.75
        ipk = _id(lut, "n", W6, Ln, 1.8 - max(n1, 0.05), 1.8 - max(n1, 0.05), max(n1, 0.0))
        preds = {"vth_hi": vhi, "vth_lo": vlo,
                 "hysteresis": min(vhi - vlo, vhi_l - vlo_l),
                 "power_avg": 1.8 * 0.35 * ipk + 2e-6}
    except Exception:
        preds = {"vth_hi": 1.2, "vth_lo": 0.35, "hysteresis": 0.85, "power_avg": 15e-6}
    return n, preds
